 'random-password':()=>{const bytes=crypto.getRandomValues(new Uint8Array(10));const v='At!'+[...bytes].map(x=>'ABCDEFGHJKMNPQRSTUVWXYZabcdefghjkmnpqrstuvwxyz23456789'[x%51]).join('')+'9';const input=$('[name="password"]',$('#modal'));if(input)input.value=v;},
 'reset-password':el=>modal('초기 비밀번호 새로 발급',`<form data-form="reset-password" data-id="${esc(el.dataset.id)}"><div class="notice mb">${esc(studentName(el.dataset.id))} 계정에 임시 비밀번호를 새로 발급합니다. 기존 비밀번호는 열람할 수 없습니다.</div>${field('새 초기 비밀번호','password','','text',`required minlength="${demo?4:12}" autocomplete="off"`)}<button class="text-btn" type="button" data-act="random-password">안전한 초기 비밀번호 자동 만들기</button>${formEnd('새 초기 비밀번호 발급')}`),
