 'create-user':async(f,v)=>{const same=(D.profiles||[]).filter(p=>p.role==='student'&&p.display_name===v.display_name.trim());if(v.role==='student'&&same.length&&!v.confirmed_distinct)throw new Error('같은 이름의 기존 학생을 먼저 확인해 주세요. 다른 학생일 때만 확인란을 선택하세요.');await api('create-user',v);closeModal();await refresh();toast('계정을 만들었습니다. 초기 비밀번호를 본인에게 안전하게 전달하세요.');},
