 'family-link':async(f,v)=>{await api('family-link',v);await loadData();familyModal();toast('학부모에게 자녀를 연결했습니다.');},
 'save-class':async(f,v)=>{if(v.ends_on<v.starts_on)throw new Error('종강일은 개강일 이후여야 합니다.');await api('save-class',{...v,id:f.dataset.id||undefined,active:!!v.active});closeModal();await refresh();toast('반 정보를 저장했습니다.');},
 'save-lesson':async(f,v)=>{
 const old=editingLesson||{};const links=(v.material_links||'').split('\n').map(s=>s.trim()).filter(Boolean).map(s=>{const bar=s.indexOf('|');if(bar<1)throw new Error('자료 링크는 “자료 이름 | https://주소” 형태로 한 줄씩 입력하세요.');return {name:s.slice(0,bar).trim(),url:s.slice(bar+1).trim()};});
 const keep=new FormData(f).getAll('keep_material');const materials=[...(old.materials||[]).filter(m=>m.asset_id&&keep.includes(m.asset_id)),...links];
 for(const file of $('[name="material_files"]',f).files){const aid=await upload(file,'material');materials.push({name:file.name,asset_id:aid});}
 let videoAsset=old.video_asset_id||null;const vf=$('[name="video_file"]',f).files[0];if(v.video_kind==='upload'&&vf)videoAsset=await upload(vf,'video');if(v.video_kind==='upload'&&!videoAsset)throw new Error('영상 파일을 선택해 주세요.');
 await api('save-lesson',{...v,id:f.dataset.id||undefined,starts_at:kst(v.starts_at),duration_min:asNum(v.duration_min),materials,video_asset_id:videoAsset});closeModal();await refresh();toast('수업 기록을 저장했습니다.');},
 'create-assignment':async(f,v)=>{const l=one('lessons',f.dataset.id);let items=[];if(v.kind==='quiz'){const rows=$$('.quiz-key-grid',f);if(rows.length!==asNum(v.count))throw new Error('문항 수를 바꾼 뒤 “문항 설정 적용”을 눌러 주세요.');items=rows.map(r=>({answer:asNum($('[data-field="answer"]',r).value),choices:5,subject:one('classes',l.class_id)?.subject||'',unit:$('[data-field="unit"]',r).value,type_tag:$('[data-field="type"]',r).value}));}
 await api('create-assignment',{lesson_id:f.dataset.id,title:v.title,instructions:v.instructions,kind:v.kind,due_at:kst(v.due_at),accept_late:!!v.accept_late,items});closeModal();await refresh();toast('과제를 등록했습니다.');},
 'assignment-deadline':async(f,v)=>{await api('assignment-deadline',{id:f.dataset.id,due_at:kst(v.due_at),accept_late:!!v.accept_late});closeModal();await refresh();toast('제출 기한을 변경했습니다.');},
 'submit-quiz':async(f,v)=>{const a=one('assignments',f.dataset.id);const answers=Array.from({length:a.question_count},(_,i)=>asNum(v['q'+(i+1)]));if(answers.some(x=>!x))throw new Error('모든 문항에 답해 주세요.');if(!confirm('답안을 최종 제출할까요? 제출 후에는 수정할 수 없습니다.'))return;await api('submit',{assignment_id:a.id,answers,asset_ids:[]});await loadData();assignmentModal(a.id);toast('답안과 제출 시각이 기록되었습니다.');},
