 'attendance':async(f)=>{for(const s of $$('select',f)){if(s.value)await api('attendance',{lesson_id:f.dataset.id,student_id:s.name,status:s.value,note:''});}closeModal();await refresh();toast('출결을 기록했습니다.');},
 'save-score':async(f,v)=>{await api('save-score',{...v,score:asNum(v.score),max_score:asNum(v.max_score)});closeModal();await refresh();toast('평가 성적을 기록했습니다.');},
 'feedback':async(f,v)=>{await api('feedback',{id:f.dataset.id,feedback:v.feedback,...(v.score!==''?{score:asNum(v.score)}:{})});closeModal();await refresh();toast('피드백을 저장했습니다.');},
 'reset-password':async(f,v)=>{await api('reset-password',{id:f.dataset.id,password:v.password});closeModal();await refresh();toast('새 초기 비밀번호를 발급했습니다.');},
 'change-credentials':async(f,v)=>{if(v.new_password!==v.confirm_password)throw new Error('새 비밀번호와 확인 비밀번호가 일치하지 않습니다.');const r=await api('change-credentials',v);if(!demo)await sb.auth.setSession(r.session);await loadData();tab='home';await render();toast('계정 정보를 변경했습니다. 학습 기록은 그대로 유지됩니다.');},
 'drive-folder':async(f,v)=>{await api('drive-folder',v);await loadDriveStatus();toast('과제 보관 폴더를 저장했습니다.');}
