document.addEventListener('click',async e=>{const el=e.target.closest('[data-act]');if(!el)return;const fn=actions[el.dataset.act];if(!fn)return;e.preventDefault();if(el.disabled)return;try{el.disabled=true;await fn(el);}catch(err){toast(err.message||String(err));}finally{el.disabled=false;}});
document.addEventListener('submit',async e=>{const f=e.target.closest('form[data-form]');if(!f||!forms[f.dataset.form])return;e.preventDefault();if(f.dataset.busy==='1')return;const button=$('button[type="submit"]',f);try{f.dataset.busy='1';if(button)button.disabled=true;const er=$('.form-error',f);if(er)er.textContent='';const v=Object.fromEntries(new FormData(f).entries());await forms[f.dataset.form](f,v);}catch(err){userError(f,err);}finally{f.dataset.busy='';if(button)button.disabled=false;}});
document.addEventListener('input',e=>{if(e.target.id==='user-search'){const b=$('#users-body');if(b)b.innerHTML=userRows();}if(e.target.name==='display_name')duplicateUsers();});
document.addEventListener('change',async e=>{try{if(e.target.id==='user-role')$('#users-body').innerHTML=userRows();if(e.target.name==='role')duplicateUsers();if(e.target.name==='kind'&&$('#quiz-settings'))$('#quiz-settings').classList.toggle('hidden',e.target.value!=='quiz');if(e.target.id==='photo-input'||e.target.id==='camera-input'){await addPhotos([...e.target.files]);e.target.value='';}if(e.target.id==='record-class'){const scores=by('scores','student_id',studentId()).filter(x=>x.class_id===e.target.value).sort((a,b)=>a.assessed_on.localeCompare(b.assessed_on));$('#record-chart').innerHTML=chart(scores.slice(-8));}}catch(err){toast(err.message);}});
$('#modal').addEventListener('close',stopVideo);
